@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14140f;
    --surface: #1c1c17;
    --surface-alt: #232319;
    --ink: #f5f3ee;
    --ink-soft: #c9c6bd;
    --ink-muted: #8e8c83;
    --line: #2c2c24;
    --accent: #d97757;
    --shadow-sm: 0 1px 2px rgba(0,0,0,0.4), 0 2px 8px rgba(0,0,0,0.3);
    --shadow-md: 0 4px 12px rgba(0,0,0,0.4), 0 12px 32px rgba(0,0,0,0.5);
  }
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem; top: -40px;
  background: var(--ink);
  color: var(--bg);
  padding: 0.5rem 0.875rem;
  border-radius: var(--radius-sm);
  z-index: 100;
  font-weight: 500;
}
.skip-link:focus { top: 0.75rem; }

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 clamp(1rem, 3vw, 2rem);
}

/* Typography */
h1, h2, h3 {
  font-family: var(--font-serif);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--ink);
  margin: 0;
  line-height: 1.1;
}
h1 { font-size: clamp(2.5rem, 5.5vw, 4.25rem); }
h2 { font-size: clamp(1.75rem, 3.2vw, 2.5rem); }
h3 { font-size: 1.125rem; line-height: 1.3; }

.eyebrow {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-muted);
  margin: 0 0 0.75rem;
}
.eyebrow-accent { color: var(--accent); }

.lede {
  color: var(--ink-soft);
  font-size: 1.0625rem;
  max-width: 48ch;
  margin: 0 0 1.5rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.5rem;
  border-radius: 999px;
  font-size: 0.9375rem;
  font-weight: 500;
  border: 1px solid transparent;
  transition: transform 0.15s ease, background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
  cursor: pointer;
  white-space: nowrap;
}
.btn-primary { background: var(--ink); color: var(--bg); }
.btn-primary:hover { transform: translateY(-1px); }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--line); }
.btn-ghost:hover { background: var(--surface-alt); }

.link-arrow {
  font-size: 0.9375rem;
  font-weight: 500;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
  align-self: flex-end;
}
.link-arrow:hover { color: var(--accent); }

/* Header */
.site-header {
  position: sticky; top: 0;
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: saturate(160%) blur(12px);
  -webkit-backdrop-filter: saturate(160%) blur(12px);
  border-bottom: 1px solid var(--line);
  z-index: 50;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  height: 72px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.brand-mark { color: var(--accent); font-size: 1.1em; }

.primary-nav ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 2rem;
}
.primary-nav a {
  font-size: 0.9375rem;
  color: var(--ink-soft);
  position: relative;
  padding: 0.25rem 0;
}
.primary-nav a:hover { color: var(--ink); }

.header-actions { display: flex; gap: 0.25rem; }
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: inline-flex;
  align-items: center; justify-content: center;
  background: transparent;
  border: none;
  color: var(--ink);
  border-radius: 999px;
  transition: background 0.2s;
}
.icon-btn:hover { background: var(--surface-alt); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  min-width: 18px; height: 18px;
  padding: 0 5px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.6875rem;
  font-weight: 600;
  border-radius: 999px;
  display: inline-flex;
  align-items: center; justify-content: center;
  line-height: 1;
}

@media (max-width: 760px) {
  .primary-nav { display: none; }
}

/* Hero */
.hero { padding: clamp(3rem, 8vw, 6rem) 0 clamp(2rem, 5vw, 4rem); }
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}
.hero-copy h1 { margin-bottom: 1.25rem; }
.hero-cta { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-bottom: 2.5rem; }
.hero-perks {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  font-size: 0.875rem;
  color: var(--ink-soft);
}
.hero-perks li { display: inline-flex; align-items: center; gap: 0.5rem; }
.hero-perks span { color: var(--accent); font-weight: 700; }

.hero-visual {
  position: relative;
  aspect-ratio: 1 / 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 0.875rem;
}
.hero-card {
  border-radius: var(--radius);
  background: var(--surface-alt);
  position: relative;
  overflow: hidden;
}
.hero-card::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.5), transparent 60%);
  mix-blend-mode: overlay;
}
.hero-card-1 {
  grid-row: 1 / span 2;
  background: linear-gradient(140deg, #d8c4a6 0%, #b89572 100%);
}
.hero-card-2 { background: linear-gradient(160deg, #e8e1d4 0%, #b4513a 130%); }
.hero-card-3 { background: linear-gradient(140deg, #2c2c24 0%, #5a5043 100%); }

@media (max-width: 860px) {
  .hero-grid { grid-template-columns: 1fr; }
  .hero-visual { aspect-ratio: 5 / 4; }
}

/* Categories */
.categories {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 1.25rem 0;
  background: var(--surface);
}
.category-list {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: clamp(1rem, 4vw, 3rem);
  overflow-x: auto;
  scrollbar-width: thin;
}
.category-list a {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--ink-soft);
  white-space: nowrap;
  font-weight: 500;
}
.category-list a:hover { color: var(--ink); }
.cat-icon {
  display: inline-flex;
  width: 28px; height: 28px;
  align-items: center; justify-content: center;
  background: var(--surface-alt);
  border-radius: 999px;
  color: var(--accent);
}

/* Sections */
.section { padding: clamp(3.5rem, 7vw, 6rem) 0; }
.section-deals { background: var(--surface); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

/* Product grid */
.product-grid {
  list-style: none;
  margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: clamp(1rem, 2.5vw, 1.75rem);
}
.product-card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.product-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.product-media {
  position: relative;
  aspect-ratio: 4 / 5;
  background: var(--surface-alt);
  overflow: hidden;
}
.product-media::before {
  content: "";
  position: absolute; inset: 12%;
  border-radius: 50%;
  background: var(--card-tone, linear-gradient(140deg, #d8c4a6, #a0805e));
  filter: blur(2px);
  opacity: 0.85;
}
.product-media::after {
  content: "";
  position: absolute; inset: 0;
  background: radial-gradient(circle at 28% 22%, rgba(255,255,255,0.45), transparent 55%);
}
.badge {
  position: absolute;
  top: 0.75rem; left: 0.75rem;
  background: var(--ink);
  color: var(--bg);
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  z-index: 2;
}
.badge-sale { background: var(--sale); }
.badge-new { background: #2f5d4f; }

.wishlist-btn {
  position: absolute;
  top: 0.625rem; right: 0.625rem;
  width: 36px; height: 36px;
  border-radius: 999px;
  background: rgba(255,255,255,0.92);
  border: none;
  color: var(--ink);
  display: inline-flex;
  align-items: center; justify-content: center;
  z-index: 2;
  transition: transform 0.15s, color 0.2s;
}
.wishlist-btn:hover { transform: scale(1.07); color: var(--accent); }
.wishlist-btn[aria-pressed="true"] { color: var(--sale); }
.wishlist-btn[aria-pressed="true"] svg { fill: currentColor; }

.product-body {
  padding: 1rem 0.25rem 0.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}
.product-cat {
  font-size: 0.75rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-muted);
  margin: 0;
}
.product-name {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 500;
  margin: 0;
  letter-spacing: 0;
}
.product-price {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin-top: 0.25rem;
}
.price-now { font-weight: 600; color: var(--ink); }
.price-was {
  color: var(--ink-muted);
  text-decoration: line-through;
  font-size: 0.875rem;
}
.price-now.is-sale { color: var(--sale); }

.product-actions { margin-top: 0.875rem; }
.add-btn {
  width: 100%;
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 0.7rem 1rem;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 500;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}
.add-btn:hover { background: var(--ink); color: var(--bg); border-color: var(--ink); }

/* Deals */
.countdown {
  display: inline-flex;
  gap: 0.5rem;
  background: var(--bg);
  border: 1px solid var(--line);
  padding: 0.5rem 0.75rem;
  border-radius: 999px;
}
.countdown-unit {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  min-width: 38px;
  font-size: 0.6875rem;
  color: var(--ink-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.countdown-unit strong {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.deals-grid {
  list-style: none;
  margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: clamp(1rem, 2.5vw, 1.5rem);
}
.deal-card {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: 1rem;
  padding: 1rem;
  background: var(--bg);
  border-radius: var(--radius);
  border: 1px solid var(--line);
  align-items: center;
}
.deal-media {
  aspect-ratio: 1 / 1;
  border-radius: var(--radius-sm);
  background: var(--card-tone, linear-gradient(140deg, #d8c4a6, #b89572));
  position: relative;
}
.deal-body { display: flex; flex-direction: column; gap: 0.25rem; }
.deal-discount {
  display: inline-block;
  background: var(--sale);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  width: max-content;
  margin-bottom: 0.25rem;
}
.deal-name { font-size: 0.9375rem; font-weight: 500; font-family: var(--font-sans); margin: 0; }
.deal-price { display: flex; gap: 0.5rem; align-items: baseline; margin-top: 0.25rem; }

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto auto;
  gap: clamp(1rem, 2.5vw, 1.75rem);
}
.editorial-card { border-radius: var(--radius); overflow: hidden; }
.editorial-feature {
  grid-row: span 2;
  grid-column: span 1;
}
.editorial-link {
  display: block;
  height: 100%;
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform 0.3s ease;
}
.editorial-link:hover { transform: translateY(-3px); }
.editorial-link:hover h3 { color: var(--accent); }

.editorial-media {
  aspect-ratio: 4 / 3;
  background: var(--surface-alt);
}
.editorial-feature .editorial-media { aspect-ratio: 4 / 5; }
.editorial-media-1 { background: linear-gradient(160deg, #2c2c24, #5a5043); }
.editorial-media-2 { background: linear-gradient(160deg, #e8e1d4, #c5b89c); }
.editorial-media-3 { background: linear-gradient(160deg, #d8c4a6, #8a6e4a); }
.editorial-media-4 { background: linear-gradient(160deg, #6b8a86, #2f4d4a); }

.editorial-body { padding: 1.25rem 1rem 1.5rem; }
.editorial-tag {
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.5rem;
  font-weight: 600;
}
.editorial-body h3 {
  font-family: var(--font-serif);
  font-size: 1.375rem;
  font-weight: 500;
  margin: 0 0 0.5rem;
  transition: color 0.2s;
}
.editorial-feature .editorial-body h3 { font-size: 1.875rem; }
.editorial-excerpt { color: var(--ink-soft); margin: 0 0 0.75rem; font-size: 0.9375rem; }
.editorial-meta { color: var(--ink-muted); font-size: 0.8125rem; margin: 0; }

@media (max-width: 860px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-feature { grid-row: span 1; grid-column: span 2; }
}
@media (max-width: 560px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-feature { grid-column: span 1; }
}

/* Newsletter */
.newsletter {
  background: var(--ink);
  color: #f5f3ee;
  padding: clamp(3rem, 6vw, 5rem) 0;
}
.newsletter h2 { color: #f5f3ee; }
.newsletter .eyebrow { color: rgba(245,243,238,0.6); }
.newsletter .lede { color: rgba(245,243,238,0.75); }
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(1.5rem, 4vw, 4rem);
  align-items: center;
}
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
  align-items: stretch;
}
.newsletter-form input {
  padding: 0.875rem 1.25rem;
  border-radius: 999px;
  border: 1px solid rgba(245,243,238,0.2);
  background: rgba(245,243,238,0.06);
  color: #f5f3ee;
  font-size: 0.9375rem;
  font-family: inherit;
  min-width: 0;
}
.newsletter-form input::placeholder { color: rgba(245,243,238,0.5); }
.newsletter-form input:focus {
  outline: 2px solid #f5f3ee;
  outline-offset: 2px;
  background: rgba(245,243,238,0.12);
}
.newsletter-form .btn-primary {
  background: #f5f3ee;
  color: var(--ink);
}
.form-status {
  grid-column: 1 / -1;
  margin: 0.25rem 0 0;
  font-size: 0.875rem;
  min-height: 1.2em;
  color: #cdebd1;
}
.form-status.is-error { color: #f3b1a4; }

@media (max-width: 720px) {
  .newsletter-inner { grid-template-columns: 1fr; }
  .newsletter-form { grid-template-columns: 1fr; }
}

/* Footer */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--line);
  padding: clamp(2.5rem, 5vw, 4rem) 0 1.5rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 2rem;
  margin-bottom: 2.5rem;
}
.footer-tag { color: var(--ink-muted); margin: 0.5rem 0 0; font-size: 0.9375rem; }
.brand-footer { font-size: 1.25rem; }
.site-footer h2 {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink);
  margin: 0 0 1rem;
}
.site-footer ul {
  list-style: none;
  padding: 0; margin: 0;
  display: grid;
  gap: 0.625rem;
}
.site-footer a { color: var(--ink-soft); font-size: 0.9375rem; }
.site-footer a:hover { color: var(--ink); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
  font-size: 0.8125rem;
  color: var(--ink-muted);
}
.footer-legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 1.25rem; }

@media (max-width: 720px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
}

/* Toast */
.toast {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%) translateY(120%);
  background: var(--ink);
  color: var(--bg);
  padding: 0.75rem 1.25rem;
  border-radius: 999px;
  font-size: 0.875rem;
  box-shadow: var(--shadow-md);
  z-index: 100;
  transition: transform 0.3s ease;
  max-width: calc(100vw - 2rem);
}
.toast.is-visible { transform: translateX(-50%) translateY(0); }

