}

/* Sections */
.section { padding: clamp(3.5rem, 7vw, 6rem) 0; }
.section-deals { background: var(--surface); }

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 2.5rem;
}

/* Product grid */
.product-grid {
  list-style: none;
