              <span class="price-now is-sale">${formatPrice(p.price)}</span>
              <span class="price-was">${formatPrice(p.was)}</span>
            </p>
            <button type="button" class="add-btn" data-add="${p.id}" style="margin-top:0.5rem;">Add to bag</button>
          </div>
        </article>
      </li>`).join("");
  };

  // Cart
  let cartItems = 0;
  const updateCart = (n) => {
    cartItems += n;
    cartCountEl.textContent = String(cartItems);
    cartBtn.setAttribute("aria-label", `Cart, ${cartItems} item${cartItems === 1 ? "" : "s"}`);
  };

  const showToast = (msg) => {
    toast.textContent = msg;
    toast.classList.add("is-visible");
